func (vector *Vector) unmarshalBinaryAsync(data []byte) error {
	r := bytes.NewReader(data)
	_, err, chErr := vector.AsyncReadFrom(r)
	if err != nil {
		return err
	}
	return <-chErr
}

func deterministicVector(size int, seed uint64) Vector {
	v := make(Vector, size)
	var mixer, tweak Element
	mixer.SetUint64(seed)
	if mixer.IsZero() {
		mixer.SetOne()
	}
	tweak.SetUint64(seed*17 + 3)
	for i := range v {
		v[i].SetUint64(uint64(i + 1))
		v[i].Mul(&v[i], &mixer)
		v[i].Add(&v[i], &tweak)
		mixer.Mul(&mixer, &tweak)
		mixer.Add(&mixer, &v[i])
		tweak.Add(&tweak, &v[i])
	}
	return v
}

func TestVectorAliasing(t *testing.T) {
	assert := require.New(t)
	sizes := []int{1, 2, 3, 4, 5, 7, 8, 9, 15, 16, 17, 64, 65}

	for _, size := range sizes {
		t.Run(fmt.Sprintf("size-%d", size), func(t *testing.T) {
			a := deterministicVector(size, 11)
			b := deterministicVector(size, 29)
			var scalar Element
			scalar.SetUint64(37)

			want := make(Vector, size)
			got := make(Vector, size)

			want.Add(a, b)
			copy(got, a)
			got.Add(got, b)
			assert.True(got.Equal(want), "Add should support res == a")

			copy(got, b)
			got.Add(a, got)
			assert.True(got.Equal(want), "Add should support res == b")

			want.Sub(a, b)
			copy(got, a)
			got.Sub(got, b)
			assert.True(got.Equal(want), "Sub should support res == a")

			copy(got, b)
			got.Sub(a, got)
			assert.True(got.Equal(want), "Sub should support res == b")

			want.ScalarMul(a, &scalar)
			copy(got, a)
			got.ScalarMul(got, &scalar)
			assert.True(got.Equal(want), "ScalarMul should support res == a")

			// the scalar may point into the vector being written
			for _, idx := range []int{0, size - 1} {
				s := a[idx]
				want.ScalarMul(a, &s)
				copy(got, a)
				got.ScalarMul(got, &got[idx])
				assert.True(got.Equal(want), "ScalarMul should support b == &res[%d]", idx)
			}

			want.Mul(a, b)
			copy(got, a)
			got.Mul(got, b)
			assert.True(got.Equal(want), "Mul should support res == a")

			copy(got, b)
			got.Mul(a, got)
			assert.True(got.Equal(want), "Mul should support res == b")
		})
	}
}

func TestVectorOps(t *testing.T) {
	parameters := gopter.DefaultTestParameters()
	if testing.Short() {
		parameters.MinSuccessfulTests = 2
	} else {
		parameters.MinSuccessfulTests = 10
	}
	properties := gopter.NewProperties(parameters)

	addVector := func(a, b Vector) bool {
		c := make(Vector, len(a))
		c.Add(a, b)

		for i := range len(a) {
			var tmp Element
			tmp.Add(&a[i], &b[i])
			if !tmp.Equal(&c[i]) {
				return false
			}
		}
		return true
	}

	subVector := func(a, b Vector) bool {
		c := make(Vector, len(a))
		c.Sub(a, b)

		for i := range len(a) {
			var tmp Element
			tmp.Sub(&a[i], &b[i])
			if !tmp.Equal(&c[i]) {
				return false
			}
		}
		return true
	}

	scalarMulVector := func(a Vector, b Element) bool {
		c := make(Vector, len(a))
		c.ScalarMul(a, &b)

		for i := range len(a) {
			var tmp Element
			tmp.Mul(&a[i], &b)
			if !tmp.Equal(&c[i]) {
				return false
			}
		}
		return true
	}

	sumVector := func(a Vector) bool {
		var sum Element
		computed := a.Sum()
		for i := range len(a) {
			sum.Add(&sum, &a[i])
		}

		return sum.Equal(&computed)
	}

	innerProductVector := func(a, b Vector) bool {
		computed := a.InnerProduct(b)
		var innerProduct Element
		for i := range len(a) {
			var tmp Element
			tmp.Mul(&a[i], &b[i])
			innerProduct.Add(&innerProduct, &tmp)
		}

		return innerProduct.Equal(&computed)
	}

	mulVector := func(a, b Vector) bool {
		c := make(Vector, len(a))
		a[0].SetUint64(0x24)
		b[0].SetUint64(0x42)
		c.Mul(a, b)

		for i := range len(a) {
			var tmp Element
			tmp.Mul(&a[i], &b[i])
			if !tmp.Equal(&c[i]) {
				return false
			}
		}
		return true
	}

	sizes := []int{1, 2, 3, 4, 8, 9, 15, 16, 24, 509, 510, 511, 512, 513, 514}
	type genPair struct {
		g1, g2 gopter.Gen
		label  string
	}

	for _, size := range sizes {
		generators := []genPair{
			{genZeroVector(size), genZeroVector(size), "zero vectors"},
			{genMaxVector(size), genMaxVector(size), "max vectors"},
			{genVector(size), genVector(size), "random vectors"},
			{genVector(size), genZeroVector(size), "random and zero vectors"},
		}
		for _, gp := range generators {
			properties.Property(fmt.Sprintf("vector addition %d - %s", size, gp.label), prop.ForAll(
				addVector,
				gp.g1,
				gp.g2,
			))

			properties.Property(fmt.Sprintf("vector subtraction %d - %s", size, gp.label), prop.ForAll(
				subVector,
				gp.g1,
				gp.g2,
			))

			properties.Property(fmt.Sprintf("vector scalar multiplication %d - %s", size, gp.label), prop.ForAll(
				scalarMulVector,
				gp.g1,
				genElement(),
			))

			properties.Property(fmt.Sprintf("vector sum %d - %s", size, gp.label), prop.ForAll(
				sumVector,
				gp.g1,
			))

			properties.Property(fmt.Sprintf("vector inner product %d - %s", size, gp.label), prop.ForAll(
				innerProductVector,
				gp.g1,
				gp.g2,
			))

			properties.Property(fmt.Sprintf("vector multiplication %d - %s", size, gp.label), prop.ForAll(
				mulVector,
				gp.g1,
				gp.g2,
			))
		}
	}

	properties.TestingRun(t, gopter.NewFormatedReporter(false, 260, os.Stdout))
}

func BenchmarkVectorOps(b *testing.B) {
	// note; to benchmark against "no asm" version, use the following
	// build tag: -tags purego
	const N = 1 << 24
	a1 := make(Vector, N)
	b1 := make(Vector, N)
	c1 := make(Vector, N)
	var mixer Element
	mixer.MustSetRandom()
	for i := 1; i < N; i++ {
		a1[i-1].SetUint64(uint64(i)).
			Mul(&a1[i-1], &mixer)
		b1[i-1].SetUint64(^uint64(i)).
			Mul(&b1[i-1], &mixer)
	}

	for n := 1 << 4; n <= N; n <<= 1 {
		b.Run(fmt.Sprintf("add %d", n), func(b *testing.B) {
			_a := a1[:n]
			_b := b1[:n]
			_c := c1[:n]
			b.ResetTimer()
			for range b.N {
				_c.Add(_a, _b)
			}
		})

		b.Run(fmt.Sprintf("sub %d", n), func(b *testing.B) {
			_a := a1[:n]
			_b := b1[:n]
			_c := c1[:n]
			b.ResetTimer()
			for range b.N {
				_c.Sub(_a, _b)
			}
		})

		b.Run(fmt.Sprintf("scalarMul %d", n), func(b *testing.B) {
			_a := a1[:n]
			_c := c1[:n]
			b.ResetTimer()
			for range b.N {
				_c.ScalarMul(_a, &mixer)
			}
		})

		b.Run(fmt.Sprintf("sum %d", n), func(b *testing.B) {
			_a := a1[:n]
			b.ResetTimer()
			for range b.N {
				_ = _a.Sum()
			}
		})

		b.Run(fmt.Sprintf("innerProduct %d", n), func(b *testing.B) {
			_a := a1[:n]
			_b := b1[:n]
			b.ResetTimer()
			for range b.N {
				_ = _a.InnerProduct(_b)
			}
		})

		b.Run(fmt.Sprintf("mul %d", n), func(b *testing.B) {
			_a := a1[:n]
			_b := b1[:n]
			_c := c1[:n]
			b.ResetTimer()
			for range b.N {
				_c.Mul(_a, _b)
			}
		})
	}
}

func genZeroVector(size int) gopter.Gen {
	return func(genParams *gopter.GenParameters) *gopter.GenResult {
		g := make(Vector, size)
		genResult := gopter.NewGenResult(g, gopter.NoShrinker)
		return genResult
	}
}

func genMaxVector(size int) gopter.Gen {
	return func(genParams *gopter.GenParameters) *gopter.GenResult {
		g := make(Vector, size)

		qMinusOne := qElement
		qMinusOne[0]--

		for i := range size {
			g[i] = qMinusOne
		}
		genResult := gopter.NewGenResult(g, gopter.NoShrinker)
		return genResult
	}
}

func genVector(size int) gopter.Gen {
	return func(genParams *gopter.GenParameters) *gopter.GenResult {
		g := make(Vector, size)
		mixer := Element{
			uint32(genParams.NextUint64()),
		}
		if qElement[0] != ^uint32(0) {
			mixer[0] %= (qElement[0] + 1)
		}

		for !mixer.smallerThanModulus() {
			mixer = Element{
				uint32(genParams.NextUint64()),
			}
			if qElement[0] != ^uint32(0) {
				mixer[0] %= (qElement[0] + 1)
			}
		}

		for i := 1; i <= size; i++ {
			g[i-1].SetUint64(uint64(i)).
				Mul(&g[i-1], &mixer)
		}

		genResult := gopter.NewGenResult(g, gopter.NoShrinker)
		return genResult
	}
}

func TestReadMismatchLength(t *testing.T) {
	// ensure that the reader returns an error if the length encoded is larger than the actual
	// input.
	assert := require.New(t)

	v1 := make(Vector, 4)
	v1.MustSetRandom()

	buf := new(bytes.Buffer)
	_, err := v1.WriteTo(buf)
	assert.NoError(err, "writing to buffer should not error out")
	bufBytes := buf.Bytes()

	// tamper with the length: set it to 10
	binary.BigEndian.PutUint32(bufBytes[0:4], 10)

	var v2 Vector
	_, err = v2.ReadFrom(bytes.NewReader(bufBytes))
	assert.Error(err, "should error out as the length encoded is larger than the input")
	var v3 Vector
	err = v3.unmarshalBinaryAsync(bufBytes)
	assert.Error(err, "should error out as the length encoded is larger than the input")
	var v4 Vector
	err = v4.UnmarshalBinary(bufBytes)
	assert.Error(err, "should error out as the length encoded is larger than the input")
}

func TestReadTamperedHeader(t *testing.T) {
	assert := require.New(t)

	// Announce enough elements to detect an allocation or receiver mutation while
	// keeping this regression test safe to run without the length guard.
	var input [4]byte
	binary.BigEndian.PutUint32(input[:], 1<<12)

	newVector := func() Vector {
		v := make(Vector, 1)
		v[0].SetUint64(42)
		return v
	}
	assertUnchanged := func(v Vector) {
		assert.Len(v, 1)
		assert.Equal(1, cap(v))
		assert.Equal(uint64(42), v[0].Uint64())
	}

	v := newVector()
	n, err, errCh := v.AsyncReadFrom(bytes.NewReader(input[:]))
	assert.Equal(int64(4), n)
	assert.ErrorIs(err, io.ErrUnexpectedEOF)
	_, open := <-errCh
	assert.False(open)
	assertUnchanged(v)

	v = newVector()
	n, err = v.ReadFrom(bytes.NewReader(input[:]))
	assert.Equal(int64(4), n)
	assert.ErrorIs(err, io.ErrUnexpectedEOF)
	assertUnchanged(v)

	v = newVector()
	err = v.UnmarshalBinary(input[:])
	assert.True(errors.Is(err, io.ErrUnexpectedEOF))
	assertUnchanged(v)
}

func TestReadTamperedHeaderWithoutLen(t *testing.T) {
	assert := require.New(t)

	v1 := make(Vector, 4)
	v1.MustSetRandom()
	buf := new(bytes.Buffer)
	_, err := v1.WriteTo(buf)
	assert.NoError(err)
	bufBytes := buf.Bytes()
	binary.BigEndian.PutUint32(bufBytes[:4], 1<<12)

	readerWithoutLen := func() io.Reader {
		return struct{ io.Reader }{Reader: bytes.NewReader(bufBytes)}
	}

	r := readerWithoutLen()
	_, hasLen := r.(interface{ Len() int })
	assert.False(hasLen)
	var v2 Vector
	n, err := v2.ReadFrom(r)
	assert.Equal(int64(len(bufBytes)), n)
	assert.Error(err)

	var v3 Vector
	n, err, errCh := v3.AsyncReadFrom(readerWithoutLen())
	assert.Equal(int64(len(bufBytes)), n)
	assert.Error(err)
	_, open := <-errCh
	assert.False(open)
}

func TestReuseSliceDeserialization(t *testing.T) {
	// test that when we deserialize into a preallocated slice, if the slice is
	// large enough, we reuse it (and don't allocate a new one)
	const (
		size     = 1 << 16
		capacity = 1 << 20
	)
	assert := require.New(t)

	v1 := make(Vector, size)
	v1.MustSetRandom()

	buf := new(bytes.Buffer)
	_, err := v1.WriteTo(buf)
	assert.NoError(err, "writing to buffer should not error out")

	bufBytes := buf.Bytes()

	v2 := make(Vector, capacity)
	_, err = v2.ReadFrom(bytes.NewReader(bufBytes))
	assert.NoError(err, "should read without error")
	assert.Equal(size, len(v2), "length of the slice should equal to the original one")
	assert.Equal(capacity, cap(v2), "capacity of the slice should remain unchanged")
	assert.True(v1.Equal(v2), "vectors should be equal")
	v3 := make(Vector, capacity)
	_, err, errCh := v3.AsyncReadFrom(bytes.NewReader(bufBytes))
	assert.NoError(err, "should read without error")
	assert.NoError(<-errCh, "should validate without error")
	assert.Equal(size, len(v3), "length of the slice should equal to the original one")
	assert.Equal(capacity, cap(v3), "capacity of the slice should remain unchanged")
	assert.True(v1.Equal(v3), "vectors should be equal")
}

